# =====================================================================
#  AD MANAGER - WINDOWS 11 EDITION (WPF)
#  Consulta e Desbloqueio de Usuarios do Active Directory
# =====================================================================

# ---------- AUTO-ELEVACAO ----------
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Start-Process powershell.exe -ArgumentList @(
        "-NoProfile",
        "-ExecutionPolicy","Bypass",
        "-WindowStyle","Hidden",
        "-File","`"$PSCommandPath`""
    ) -Verb RunAs -WindowStyle Hidden
    exit
}

# ---------- ESCONDE CONSOLE PROPRIO (caso exista) ----------
Add-Type -Name HideWin -Namespace ADM -MemberDefinition '
[System.Runtime.InteropServices.DllImport("kernel32.dll")]
public static extern System.IntPtr GetConsoleWindow();
[System.Runtime.InteropServices.DllImport("user32.dll")]
public static extern bool ShowWindow(System.IntPtr hWnd, int nCmdShow);'
$h = [ADM.HideWin]::GetConsoleWindow()
if ($h -ne [IntPtr]::Zero) { [ADM.HideWin]::ShowWindow($h, 0) | Out-Null }

# ---------- ASSEMBLIES ----------
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase
Add-Type -AssemblyName System.Windows.Forms

# ---------- MODULO AD ----------
$script:adAvailable = $false
try {
    Import-Module ActiveDirectory -ErrorAction Stop
    $script:adAvailable = $true
} catch {
    $script:adAvailable = $false
}

# ---------- ICONE DO PROGRAMA (embutido em base64) ----------
$script:IconBase64 = @'
AAABAAEAAMAAAAEAIAAoGAMAFgAAACgAAAAAAQAAgAEAAAEAIAAAAAAAAAADACMuAAAjLgAAAAAA
AAAAAAD/////////////////////////////////////////////////////////////////////
