'@

$script:WindowIcon = $null
try {
    $iconBytes = [Convert]::FromBase64String(($script:IconBase64 -replace '\s',''))
    $iconStream = New-Object System.IO.MemoryStream(,$iconBytes)
    $bmp = New-Object System.Windows.Media.Imaging.BitmapImage
    $bmp.BeginInit()
    $bmp.StreamSource = $iconStream
    $bmp.CacheOption  = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
    $bmp.EndInit()
    $bmp.Freeze()
    $script:WindowIcon = $bmp
} catch {
    $script:WindowIcon = $null
}

# ===================== XAML =====================
[xml]$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="AD Manager"
        Height="780" Width="1300"
        MinHeight="680" MinWidth="1100"
        WindowStartupLocation="CenterScreen"
        Background="#202020"
        FontFamily="Segoe UI Variable Text, Segoe UI"
        Foreground="#FFFFFF"
        TextOptions.TextFormattingMode="Ideal"
        TextOptions.TextRenderingMode="ClearType">

    <Window.Resources>

        <SolidColorBrush x:Key="BgBase"      Color="#202020"/>
        <SolidColorBrush x:Key="BgCard"      Color="#2B2B2B"/>
        <SolidColorBrush x:Key="BgInput"     Color="#2D2D2D"/>
        <SolidColorBrush x:Key="Border1"     Color="#3F3F3F"/>
        <SolidColorBrush x:Key="TextPrimary" Color="#FFFFFF"/>
        <SolidColorBrush x:Key="TextSecond"  Color="#C7C7C7"/>
        <SolidColorBrush x:Key="TextDim"     Color="#9D9D9D"/>
        <SolidColorBrush x:Key="TextMute"    Color="#7A7A7A"/>
        <SolidColorBrush x:Key="Accent"      Color="#4CC2FF"/>
        <SolidColorBrush x:Key="AccentHover" Color="#67CDFF"/>
        <SolidColorBrush x:Key="Success"     Color="#6CCB5F"/>
        <SolidColorBrush x:Key="SuccessBg"   Color="#1F3823"/>
        <SolidColorBrush x:Key="Warning"     Color="#FCE100"/>
        <SolidColorBrush x:Key="WarningBg"   Color="#3D3717"/>
        <SolidColorBrush x:Key="Danger"      Color="#FF99A4"/>
        <SolidColorBrush x:Key="DangerBg"    Color="#442726"/>
        <SolidColorBrush x:Key="DangerBorder" Color="#7A3537"/>

        <Style x:Key="Card" TargetType="Border">
            <Setter Property="Background" Value="{StaticResource BgCard}"/>
            <Setter Property="BorderBrush" Value="{StaticResource Border1}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="CornerRadius" Value="8"/>
            <Setter Property="Effect">
                <Setter.Value>
                    <DropShadowEffect Color="Black" BlurRadius="20" Opacity="0.25" ShadowDepth="2"/>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="AccentButton" TargetType="Button">
            <Setter Property="Background" Value="{StaticResource Accent}"/>
            <Setter Property="Foreground" Value="#000000"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource AccentHover}"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="Bd" Property="Background" Value="#3A3A3A"/>
                                <Setter Property="Foreground" Value="#7A7A7A"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="SecondaryButton" TargetType="Button">
            <Setter Property="Background" Value="#373737"/>
            <Setter Property="Foreground" Value="{StaticResource TextPrimary}"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}"
                                BorderBrush="{StaticResource Border1}" BorderThickness="1"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="#454545"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter Property="Foreground" Value="#7A7A7A"/>
                                <Setter TargetName="Bd" Property="Background" Value="#2A2A2A"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="SuccessButton" TargetType="Button">
            <Setter Property="Background" Value="#107C10"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="#138A13"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="Bd" Property="Background" Value="#3A3A3A"/>
                                <Setter Property="Foreground" Value="#7A7A7A"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="ModernTextBox" TargetType="TextBox">
            <Setter Property="Background" Value="{StaticResource BgInput}"/>
            <Setter Property="Foreground" Value="{StaticResource TextPrimary}"/>
            <Setter Property="BorderBrush" Value="{StaticResource Border1}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="Padding" Value="14,0"/>
            <Setter Property="FontSize" Value="14"/>
            <Setter Property="CaretBrush" Value="{StaticResource TextPrimary}"/>
            <Setter Property="SelectionBrush" Value="{StaticResource Accent}"/>
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TextBox">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}"
                                BorderBrush="{TemplateBinding BorderBrush}"
                                BorderThickness="{TemplateBinding BorderThickness}"
                                CornerRadius="4">
                            <ScrollViewer x:Name="PART_ContentHost"
                                          Padding="{TemplateBinding Padding}"
                                          VerticalAlignment="Center"
                                          Background="Transparent"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="HistoryItemButton" TargetType="Button">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="{StaticResource TextPrimary}"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="HorizontalAlignment" Value="Stretch"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Padding" Value="10,6"/>
            <Setter Property="Margin" Value="0,1"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}"
                                BorderBrush="Transparent" BorderThickness="1"
                                CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="#373737"/>
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Border1}"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="#454545"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="CardHeader" TargetType="Border">
            <Setter Property="Padding" Value="20,14"/>
            <Setter Property="BorderBrush" Value="{StaticResource Border1}"/>
            <Setter Property="BorderThickness" Value="0,0,0,1"/>
        </Style>

    </Window.Resources>

    <Grid>
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <Border Grid.Row="0" Padding="24,18" Background="{StaticResource BgBase}">
            <Grid>
                <StackPanel Orientation="Horizontal">
                    <Border Width="36" Height="36" Background="{StaticResource Accent}" CornerRadius="8">
                        <TextBlock Text="AD" Foreground="#000000" FontSize="14" FontWeight="Bold"
                                   HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <StackPanel Margin="14,0,0,0" VerticalAlignment="Center">
                        <TextBlock Text="AD Manager" FontSize="20" FontWeight="SemiBold"
                                   Foreground="{StaticResource TextPrimary}"/>
                        <TextBlock Text="Active Directory User Console" FontSize="12"
                                   Foreground="{StaticResource TextDim}" Margin="0,-2,0,0"/>
                    </StackPanel>
                </StackPanel>

                <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
                    <Ellipse Width="8" Height="8" Fill="{StaticResource Success}" Margin="0,0,8,0"/>
                    <TextBlock Name="AdminLabel" Text="" Foreground="{StaticResource TextSecond}" FontSize="12"/>
                </StackPanel>
            </Grid>
        </Border>

        <Grid Grid.Row="1" Margin="24,8,24,12">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>

            <Grid Grid.Column="0">
                <TextBox Name="SearchBox" Style="{StaticResource ModernTextBox}" Height="40"
                         Padding="40,0,14,0"/>
                <TextBlock Name="SearchHint" Text="Digite usuario, e-mail ou nome completo..."
                           Foreground="{StaticResource TextMute}" FontSize="14"
                           VerticalAlignment="Center" Margin="40,0,0,0" IsHitTestVisible="False"/>
                <TextBlock Text="&#xE721;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                           Foreground="{StaticResource TextDim}" FontSize="14"
                           VerticalAlignment="Center" Margin="14,0,0,0" IsHitTestVisible="False"/>
            </Grid>

            <Button Name="SearchButton" Grid.Column="1" Style="{StaticResource AccentButton}"
                    Content="Consultar" Width="130" Height="40" Margin="10,0,0,0"/>
        </Grid>

        <Border Grid.Row="2" Name="NotifBanner" Margin="24,4,24,12"
                Background="{StaticResource DangerBg}"
                BorderBrush="{StaticResource DangerBorder}" BorderThickness="1"
                CornerRadius="6" Padding="16,12" Visibility="Collapsed">
            <StackPanel Orientation="Horizontal">
                <TextBlock Text="&#xE7BA;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                           Foreground="{StaticResource Danger}" FontSize="20"
                           VerticalAlignment="Center" Margin="0,0,12,0"/>
                <StackPanel VerticalAlignment="Center">
                    <TextBlock Name="NotifTitle" Text="Atencao: senha vencida"
                               Foreground="{StaticResource Danger}" FontWeight="SemiBold" FontSize="13"/>
                    <TextBlock Name="NotifText" Text=""
                               Foreground="{StaticResource TextSecond}" FontSize="12" Margin="0,2,0,0"/>
                </StackPanel>
            </StackPanel>
        </Border>

        <!-- LAYOUT REESTRUTURADO EM 4 COLUNAS LADO A LADO -->
        <Grid Grid.Row="3" Margin="24,0,24,16">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="1*"/>
                <ColumnDefinition Width="1.2*"/>
                <ColumnDefinition Width="1*"/>
                <ColumnDefinition Width="0.85*"/>
            </Grid.ColumnDefinitions>

            <!-- COLUNA 0: Informacoes do usuario (Sem ScrollViewer) -->
            <Border Grid.Column="0" Style="{StaticResource Card}" Margin="0,0,8,0">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <Border Grid.Row="0" Style="{StaticResource CardHeader}">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Text="&#xE77B;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                                       Foreground="{StaticResource Accent}" FontSize="16"
                                       VerticalAlignment="Center" Margin="0,0,10,0"/>
                            <TextBlock Text="Informacoes do usuario" FontSize="14"
                                       FontWeight="SemiBold" Foreground="{StaticResource TextPrimary}"
                                       VerticalAlignment="Center"/>
                        </StackPanel>
                    </Border>
                    <!-- Apenas StackPanel para nao ter rolagem -->
                    <StackPanel Grid.Row="1" Name="UserInfoStack" Margin="20,16,20,16"/>
                </Grid>
            </Border>

            <!-- COLUNA 1: Informacoes da conta (Sem ScrollViewer) -->
            <Border Grid.Column="1" Style="{StaticResource Card}" Margin="0,0,8,0">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <Border Grid.Row="0" Style="{StaticResource CardHeader}">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Text="&#xE72E;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                                       Foreground="{StaticResource Accent}" FontSize="16"
                                       VerticalAlignment="Center" Margin="0,0,10,0"/>
                            <TextBlock Text="Informacoes da conta" FontSize="14"
                                       FontWeight="SemiBold" Foreground="{StaticResource TextPrimary}"
                                       VerticalAlignment="Center"/>
                        </StackPanel>
                    </Border>
                    <Grid Grid.Row="1">
                        <StackPanel Name="AccountInfoStack" Margin="20,16,20,16"/>
                        <StackPanel Name="EmptyState" VerticalAlignment="Center"
                                    HorizontalAlignment="Center" Margin="20,30">
                            <TextBlock Text="&#xE7B5;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                                       FontSize="40" Foreground="{StaticResource TextMute}"
                                       HorizontalAlignment="Center"/>
                            <TextBlock Text="Nenhum usuario consultado"
                                       FontSize="13" Foreground="{StaticResource TextDim}"
                                       HorizontalAlignment="Center" Margin="0,12,0,4"/>
                            <TextBlock Text="Digite um usuario ou e-mail acima"
                                       FontSize="11" Foreground="{StaticResource TextMute}"
                                       HorizontalAlignment="Center"/>
                        </StackPanel>
                    </Grid>
                </Grid>
            </Border>

            <!-- COLUNA 2: Grupos (Ordem alfabetica - ScrollViewer + StackPanel vertical) -->
            <Border Grid.Column="2" Style="{StaticResource Card}" Margin="0,0,8,0">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <Border Grid.Row="0" Style="{StaticResource CardHeader}">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Text="&#xE902;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                                       Foreground="{StaticResource Accent}" FontSize="16"
                                       VerticalAlignment="Center" Margin="0,0,10,0"/>
                            <TextBlock Text="Grupos" FontSize="14"
                                       FontWeight="SemiBold" Foreground="{StaticResource TextPrimary}"
                                       VerticalAlignment="Center"/>
                            <Border Background="#3A3A3A" CornerRadius="10"
                                    Padding="8,2" Margin="8,0,0,0" VerticalAlignment="Center">
                                <TextBlock Name="GroupsCount" Text="0" FontSize="11" FontWeight="SemiBold"
                                           Foreground="{StaticResource TextSecond}"/>
                            </Border>
                        </StackPanel>
                    </Border>
                    <!-- ScrollViewer + StackPanel vertical para listagem alfabetica clara -->
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto"
                                  HorizontalScrollBarVisibility="Disabled" Margin="14,12,8,12">
                        <StackPanel Name="GroupsStack"/>
                    </ScrollViewer>
                </Grid>
            </Border>

            <!-- COLUNA 3: Historico das ultimas consultas -->
            <Border Grid.Column="3" Style="{StaticResource Card}">
                <Grid>
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <Border Grid.Row="0" Style="{StaticResource CardHeader}">
                        <Grid>
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE81C;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                                           Foreground="{StaticResource Accent}" FontSize="16"
                                           VerticalAlignment="Center" Margin="0,0,10,0"/>
                                <TextBlock Text="Historico" FontSize="14"
                                           FontWeight="SemiBold" Foreground="{StaticResource TextPrimary}"
                                           VerticalAlignment="Center"/>
                                <Border Background="#3A3A3A" CornerRadius="10"
                                        Padding="8,2" Margin="8,0,0,0" VerticalAlignment="Center">
                                    <TextBlock Name="HistoryCount" Text="0" FontSize="11" FontWeight="SemiBold"
                                               Foreground="{StaticResource TextSecond}"/>
                                </Border>
                            </StackPanel>
                            <Button Name="BtnClearHistory" HorizontalAlignment="Right"
                                    VerticalAlignment="Center" Cursor="Hand"
                                    Background="Transparent" BorderThickness="0"
                                    Foreground="{StaticResource TextDim}"
                                    ToolTip="Limpar historico" Padding="6,2">
                                <Button.Template>
                                    <ControlTemplate TargetType="Button">
                                        <Border x:Name="Bd" Background="Transparent" CornerRadius="4" Padding="{TemplateBinding Padding}">
                                            <TextBlock Text="&#xE74D;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                                                       FontSize="12" Foreground="{TemplateBinding Foreground}"/>
                                        </Border>
                                        <ControlTemplate.Triggers>
                                            <Trigger Property="IsMouseOver" Value="True">
                                                <Setter TargetName="Bd" Property="Background" Value="#3A3A3A"/>
                                                <Setter Property="Foreground" Value="{StaticResource Danger}"/>
                                            </Trigger>
                                        </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </Button.Template>
                            </Button>
                        </Grid>
                    </Border>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto"
                                  HorizontalScrollBarVisibility="Disabled" Margin="8,12,8,12">
                        <StackPanel Name="HistoryStack"/>
                    </ScrollViewer>
                </Grid>
            </Border>

        </Grid>

        <Border Grid.Row="4" Padding="24,0,24,16">
            <StackPanel Orientation="Horizontal">
                <Button Name="BtnUnlock" Style="{StaticResource SuccessButton}"
                        Content="Desbloquear conta" Width="200" Height="40" Margin="0,0,8,0"
                        IsEnabled="False"/>
                <Button Name="BtnRefresh" Style="{StaticResource SecondaryButton}"
                        Content="Atualizar" Width="140" Height="40" Margin="0,0,8,0"
                        IsEnabled="False"/>
                <Button Name="BtnScreenshot" Style="{StaticResource SecondaryButton}"
                        Content="Screenshot" Width="120" Height="40"/>
            </StackPanel>
        </Border>

        <Border Grid.Row="5" Padding="24,10" Background="#1A1A1A"
                BorderBrush="{StaticResource Border1}" BorderThickness="0,1,0,0">
            <StackPanel Orientation="Horizontal">
                <Ellipse Name="StatusDot" Width="8" Height="8" Fill="{StaticResource TextDim}"
                         VerticalAlignment="Center" Margin="0,0,8,0"/>
                <TextBlock Name="StatusLabel" Text="Pronto. Digite um usuario para comecar."
                           Foreground="{StaticResource TextSecond}" FontSize="12"
                           VerticalAlignment="Center"/>
            </StackPanel>
        </Border>

    </Grid>
</Window>
'@

# ===================== CARREGA XAML =====================
$reader = New-Object System.Xml.XmlNodeReader $xaml
$window = [Windows.Markup.XamlReader]::Load($reader)

$xaml.SelectNodes("//*[@Name]") | ForEach-Object {
    Set-Variable -Name $_.Name -Value $window.FindName($_.Name) -Scope Script
}

# Aplicar icone na janela principal
if ($script:WindowIcon) {
    try { $window.Icon = $script:WindowIcon } catch {}
}

$script:currentUser = $null

# ===================== HISTORICO =====================
$script:HistoryFolder = Join-Path $env:APPDATA 'AD_Manager'
$script:HistoryFile   = Join-Path $script:HistoryFolder 'history.json'
$script:MaxHistory    = 15
$script:SearchHistory = @()

function Load-History {
    $script:SearchHistory = @()
    if (Test-Path $script:HistoryFile) {
        try {
            $raw = Get-Content $script:HistoryFile -Raw -Encoding UTF8
            if (-not [string]::IsNullOrWhiteSpace($raw)) {
                $data = $raw | ConvertFrom-Json
                if ($data) { $script:SearchHistory = @($data) }
            }
        } catch {
            $script:SearchHistory = @()
        }
    }
}

function Save-History {
    try {
        if (-not (Test-Path $script:HistoryFolder)) {
            New-Item -ItemType Directory -Path $script:HistoryFolder -Force | Out-Null
        }
        ,$script:SearchHistory | ConvertTo-Json -Depth 4 | Set-Content -Path $script:HistoryFile -Encoding UTF8
    } catch {}
}

function Add-HistoryEntry {
    param([string]$Username, [string]$Name, [string]$Status)
    if ([string]::IsNullOrWhiteSpace($Username)) { return }

    # Remove entrada existente para o mesmo usuario (case-insensitive)
    $script:SearchHistory = @($script:SearchHistory | Where-Object {
        $_ -and $_.Username -and ($_.Username.ToString().ToLower() -ne $Username.ToLower())
    })

    $entry = [pscustomobject]@{
        Username  = $Username
        Name      = $Name
        Status    = $Status
        Timestamp = (Get-Date).ToString('yyyy-MM-ddTHH:mm:ss')
    }

    $script:SearchHistory = @(@($entry) + $script:SearchHistory) | Select-Object -First $script:MaxHistory
    Save-History
    Render-History
}

function Clear-History {
    $script:SearchHistory = @()
    Save-History
    Render-History
}

function Render-History {
    $HistoryStack.Children.Clear()

    if (-not $script:SearchHistory -or $script:SearchHistory.Count -eq 0) {
        $empty = New-Object System.Windows.Controls.StackPanel
        $empty.VerticalAlignment = 'Center'
        $empty.HorizontalAlignment = 'Center'
        $empty.Margin = '10,30'

        $ico = New-Object System.Windows.Controls.TextBlock
        $ico.Text = [char]0xE823
        $ico.FontFamily = New-Object System.Windows.Media.FontFamily('Segoe MDL2 Assets,Segoe Fluent Icons')
        $ico.FontSize = 28
        $ico.Foreground = (Get-Brush 'TextMute')
        $ico.HorizontalAlignment = 'Center'
        [void]$empty.Children.Add($ico)

        $msg = New-Object System.Windows.Controls.TextBlock
        $msg.Text = 'Nenhuma consulta recente'
        $msg.Foreground = (Get-Brush 'TextDim')
        $msg.FontSize = 12
        $msg.HorizontalAlignment = 'Center'
        $msg.Margin = '0,8,0,0'
        [void]$empty.Children.Add($msg)

        [void]$HistoryStack.Children.Add($empty)
        $HistoryCount.Text = '0'
        return
    }

    foreach ($item in $script:SearchHistory) {
        if (-not $item -or -not $item.Username) { continue }

        $btn = New-Object System.Windows.Controls.Button
        $btn.Style = $window.FindResource('HistoryItemButton')
        $btn.Tag = $item.Username
        $btn.ToolTip = "Reconsultar '$($item.Username)'"

        $sp = New-Object System.Windows.Controls.StackPanel

        # Linha 1: Nome (ou username)
        $line1 = New-Object System.Windows.Controls.TextBlock
        if ($item.Name) {
            $line1.Text = $item.Name
        } else {
            $line1.Text = $item.Username
        }
        $line1.FontSize = 13
        $line1.FontWeight = 'SemiBold'
        $line1.Foreground = (Get-Brush 'TextPrimary')
        $line1.TextTrimming = 'CharacterEllipsis'
        [void]$sp.Children.Add($line1)

        # Linha 2: username + timestamp
        $line2 = New-Object System.Windows.Controls.TextBlock
        $tsText = ''
        try {
            $ts = [DateTime]::Parse($item.Timestamp)
            $tsText = $ts.ToString('dd/MM HH:mm')
        } catch {}

        if ($item.Name) {
            $line2.Text = "$($item.Username) " + [char]0x2022 + " $tsText"
        } else {
            $line2.Text = $tsText
        }
        $line2.FontSize = 11
        $line2.Foreground = (Get-Brush 'TextDim')
        $line2.Margin = '0,2,0,0'
        $line2.TextTrimming = 'CharacterEllipsis'
        [void]$sp.Children.Add($line2)

        $btn.Content = $sp

        $btn.Add_Click({
            $SearchBox.Text = $this.Tag
            Search-User
        }.GetNewClosure())

        [void]$HistoryStack.Children.Add($btn)
    }

    $HistoryCount.Text = [string]$script:SearchHistory.Count
}


# ===================== HELPERS =====================
function Get-Brush { param($key) return $window.FindResource($key) }

function Add-InfoRow {
    param(
        [Parameter(Mandatory)] $Container,
        [Parameter(Mandatory)] [string]$Label,
        [Parameter(Mandatory)] [string]$Value,
        [string]$ValueColorKey = "TextPrimary",
        [string]$Badge = $null,
        [string]$BadgeColorKey = "Success",
        [string]$BadgeBgKey = "SuccessBg"
    )

    $row = New-Object System.Windows.Controls.StackPanel
    $row.Margin = "0,0,0,10" # Margem reduzida para evitar vazamento

    $lbl = New-Object System.Windows.Controls.TextBlock
    $lbl.Text = $Label.ToUpper()
    $lbl.FontSize = 11
    $lbl.FontWeight = "SemiBold"
    $lbl.Foreground = (Get-Brush "TextMute")
    $lbl.Margin = "0,0,0,2"
    [void]$row.Children.Add($lbl)

    $valueLine = New-Object System.Windows.Controls.StackPanel
    $valueLine.Orientation = "Horizontal"

    # SUBSTITUIDO POR TEXTBOX PARA SER COPI�VEL
    $val = New-Object System.Windows.Controls.TextBox
    $val.Text = $Value
    $val.FontSize = 14
    $val.Foreground = (Get-Brush $ValueColorKey)
    $val.VerticalAlignment = "Center"
    $val.TextWrapping = "Wrap"
    $val.IsReadOnly = $true
    $val.BorderThickness = "0"
    $val.Background = "Transparent"
    $val.Padding = "0"
    [void]$valueLine.Children.Add($val)

    if ($Badge) {
        $badgeBorder = New-Object System.Windows.Controls.Border
        $badgeBorder.Background = (Get-Brush $BadgeBgKey)
        $badgeBorder.CornerRadius = New-Object System.Windows.CornerRadius 10
        $badgeBorder.Padding = "10,3"
        $badgeBorder.Margin = "12,0,0,0"
        $badgeBorder.VerticalAlignment = "Center"

        $bt = New-Object System.Windows.Controls.TextBlock
        $bt.Text = $Badge
        $bt.FontSize = 10
        $bt.FontWeight = "SemiBold"
        $bt.Foreground = (Get-Brush $BadgeColorKey)
        $badgeBorder.Child = $bt
        [void]$valueLine.Children.Add($badgeBorder)
    }

    [void]$row.Children.Add($valueLine)
    [void]$Container.Children.Add($row)
}

function Add-GroupItem {
    param($Container, [string]$Name)
    $b = New-Object System.Windows.Controls.Border
    $b.Background = "Transparent"
    $b.CornerRadius = New-Object System.Windows.CornerRadius 4
    $b.Padding = "10,5"
    $b.Margin = "0,1"

    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Orientation = "Horizontal"

    $dot = New-Object System.Windows.Shapes.Ellipse
    $dot.Width = 6; $dot.Height = 6
    $dot.Fill = (Get-Brush "Accent")
    $dot.VerticalAlignment = "Center"
    $dot.Margin = "0,0,8,0"
    [void]$sp.Children.Add($dot)

    # SUBSTITUIDO POR TEXTBOX PARA SER COPI�VEL
    $tb = New-Object System.Windows.Controls.TextBox
    $tb.Text = $Name
    $tb.FontSize = 13
    $tb.Foreground = (Get-Brush "TextSecond")
    $tb.VerticalAlignment = "Center"
    $tb.IsReadOnly = $true
    $tb.BorderThickness = "0"
    $tb.Background = "Transparent"
    $tb.Padding = "0"
    $tb.TextWrapping = "Wrap"
    [void]$sp.Children.Add($tb)

    $b.Child = $sp
    [void]$Container.Children.Add($b)
}

function Set-Status {
    param([string]$Text, [string]$DotColorKey = "TextDim")
    $StatusLabel.Text = $Text
    $StatusDot.Fill = (Get-Brush $DotColorKey)
}

function Show-EmptyState {
    param([bool]$Show = $true)
    $EmptyState.Visibility = if ($Show) { 'Visible' } else { 'Collapsed' }
}

function Show-Notification {
    param([string]$Text)
    $NotifText.Text = $Text
    $NotifBanner.Visibility = 'Visible'
}

function Hide-Notification {
    $NotifBanner.Visibility = 'Collapsed'
}

function Get-PasswordExpiryInfo {
    param($User)

    $result = [pscustomobject]@{
        Text = ""; IsExpired = $false; NeverExp = $false
        BadgeKey = "Success"; BadgeBgKey = "SuccessBg"; Badge = "VALIDA"
    }

    if ($User.PasswordNeverExpires) {
        $result.Text = "Nunca expira"; $result.NeverExp = $true
        $result.BadgeKey = "Warning"; $result.BadgeBgKey = "WarningBg"; $result.Badge = "NAO EXPIRA"
        return $result
    }

    if ($User.PasswordExpired) {
        $result.Text = "Expirada (troca obrigatoria)"; $result.IsExpired = $true
        $result.BadgeKey = "Danger"; $result.BadgeBgKey = "DangerBg"; $result.Badge = "VENCIDA"
        $ft = $User."msDS-UserPasswordExpiryTimeComputed"
        if ($ft -and $ft -gt 0 -and $ft -lt 9223372036854775807) {
            try {
                $d = [DateTime]::FromFileTime($ft)
                $diff = ((Get-Date) - $d).Days
                $result.Text = "Expirada em $($d.ToString('dd/MM/yyyy HH:mm')) (ha $diff dia(s))"
            } catch {}
        }
        return $result
    }

    $ft = $User."msDS-UserPasswordExpiryTimeComputed"
    if (-not $ft -or $ft -eq 0) {
        $result.Text = "Troca obrigatoria no proximo login"; $result.IsExpired = $true
        $result.BadgeKey = "Danger"; $result.BadgeBgKey = "DangerBg"; $result.Badge = "TROCAR"
        return $result
    }
    if ($ft -eq 9223372036854775807) {
        $result.Text = "Nunca expira"; $result.NeverExp = $true
        $result.BadgeKey = "Warning"; $result.BadgeBgKey = "WarningBg"; $result.Badge = "NAO EXPIRA"
        return $result
    }

    try {
        $d = [DateTime]::FromFileTime($ft)
        $now = Get-Date
        if ($d -lt $now) {
            $diff = ($now - $d).Days
            $result.Text = "Expirada em $($d.ToString('dd/MM/yyyy HH:mm')) (ha $diff dia(s))"
            $result.IsExpired = $true
            $result.BadgeKey = "Danger"; $result.BadgeBgKey = "DangerBg"; $result.Badge = "VENCIDA"
        } else {
            $diff = ($d - $now).Days
            $result.Text = "$($d.ToString('dd/MM/yyyy HH:mm')) (em $diff dia(s))"
            if ($diff -le 7) {
                $result.BadgeKey = "Warning"; $result.BadgeBgKey = "WarningBg"; $result.Badge = "EXPIRA EM BREVE"
            }
        }
    } catch {
        $result.Text = "Indeterminada"
    }

    return $result
}

function Show-UserSelectionDialog {
    param(
        [Parameter(Mandatory)] $Users,
        [string]$Query
    )

    [xml]$dxaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Selecionar usuario"
        Width="640" Height="480"
        WindowStartupLocation="CenterOwner"
        Background="#202020"
        FontFamily="Segoe UI Variable Text, Segoe UI"
        Foreground="#FFFFFF"
        ResizeMode="CanResize">
    <Grid Margin="20">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
        </Grid.RowDefinitions>

        <StackPanel Grid.Row="0" Orientation="Horizontal">
            <TextBlock Text="&#xE716;" FontFamily="Segoe MDL2 Assets,Segoe Fluent Icons"
                       FontSize="22" Foreground="#4CC2FF" VerticalAlignment="Center" Margin="0,0,10,0"/>
            <TextBlock Text="Multiplos usuarios encontrados" FontSize="18"
                       FontWeight="SemiBold" VerticalAlignment="Center"/>
        </StackPanel>

        <TextBlock Grid.Row="1" Name="DlgInfo" FontSize="12" Foreground="#9D9D9D"
                   Margin="0,6,0,12" TextWrapping="Wrap"/>

        <Border Grid.Row="2" Background="#2B2B2B" BorderBrush="#3F3F3F"
                BorderThickness="1" CornerRadius="6">
            <ListBox Name="UserList" Background="Transparent" BorderThickness="0"
                     Foreground="White" FontSize="13"
                     HorizontalContentAlignment="Stretch"
                     ScrollViewer.HorizontalScrollBarVisibility="Disabled">
                <ListBox.ItemContainerStyle>
                    <Style TargetType="ListBoxItem">
                        <Setter Property="Padding" Value="10,8"/>
                        <Setter Property="Background" Value="Transparent"/>
                        <Setter Property="BorderThickness" Value="0"/>
                        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
                        <Setter Property="Cursor" Value="Hand"/>
                        <Setter Property="Template">
                            <Setter.Value>
                                <ControlTemplate TargetType="ListBoxItem">
                                    <Border x:Name="Bd" Background="{TemplateBinding Background}"
                                            BorderBrush="#3F3F3F" BorderThickness="0,0,0,1"
                                            Padding="{TemplateBinding Padding}">
                                        <ContentPresenter HorizontalAlignment="Stretch"/>
                                    </Border>
                                    <ControlTemplate.Triggers>
                                        <Trigger Property="IsMouseOver" Value="True">
                                            <Setter TargetName="Bd" Property="Background" Value="#373737"/>
                                        </Trigger>
                                        <Trigger Property="IsSelected" Value="True">
                                            <Setter TargetName="Bd" Property="Background" Value="#0E4A66"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </Setter.Value>
                        </Setter>
                    </Style>
                </ListBox.ItemContainerStyle>
            </ListBox>
        </Border>

        <StackPanel Grid.Row="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
            <Button Name="BtnDlgCancel" Content="Cancelar" Width="110" Height="36"
                    Background="#373737" Foreground="White" BorderBrush="#3F3F3F"
                    BorderThickness="1" FontWeight="SemiBold" FontSize="13"
                    Cursor="Hand" Margin="0,0,8,0"/>
            <Button Name="BtnDlgSelect" Content="Selecionar" Width="130" Height="36"
                    Background="#4CC2FF" Foreground="#000000" BorderThickness="0"
                    FontWeight="SemiBold" FontSize="13" Cursor="Hand" IsDefault="True"/>
        </StackPanel>
    </Grid>
</Window>
'@

    $dr = New-Object System.Xml.XmlNodeReader $dxaml
    $dlg = [Windows.Markup.XamlReader]::Load($dr)
    try { $dlg.Owner = $window } catch {}
    if ($script:WindowIcon) { try { $dlg.Icon = $script:WindowIcon } catch {} }

    $dlgInfo   = $dlg.FindName('DlgInfo')
    $userList  = $dlg.FindName('UserList')
    $btnSelect = $dlg.FindName('BtnDlgSelect')
    $btnCancel = $dlg.FindName('BtnDlgCancel')

    $dlgInfo.Text = "Foram encontrados $($Users.Count) usuarios para '$Query'. Selecione um abaixo (duplo clique para selecionar):"

    foreach ($u in $Users) {
        $sp = New-Object System.Windows.Controls.StackPanel

        $line1 = New-Object System.Windows.Controls.TextBlock
        $nm = if ($u.DisplayName) { $u.DisplayName } else { $u.Name }
        $line1.Text = $nm
        $line1.FontSize = 14
        $line1.FontWeight = 'SemiBold'
        $line1.Foreground = [System.Windows.Media.Brushes]::White
        [void]$sp.Children.Add($line1)

        $line2 = New-Object System.Windows.Controls.TextBlock
        $detail = $u.SamAccountName
        if ($u.EmailAddress) { $detail = "$detail  -  $($u.EmailAddress)" }
        $line2.Text = $detail
        $line2.FontSize = 11
        $line2.Foreground = (New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#9D9D9D')))
        $line2.Margin = '0,2,0,0'
        [void]$sp.Children.Add($line2)

        $item = New-Object System.Windows.Controls.ListBoxItem
        $item.Content = $sp
        $item.Tag = $u
        [void]$userList.Items.Add($item)
    }

    if ($userList.Items.Count -gt 0) { $userList.SelectedIndex = 0 }

    $script:dlgResult = $null

    $userList.Add_MouseDoubleClick({
        if ($userList.SelectedItem) {
            $script:dlgResult = $userList.SelectedItem.Tag
            $dlg.Close()
        }
    })

    $btnSelect.Add_Click({
        if ($userList.SelectedItem) {
            $script:dlgResult = $userList.SelectedItem.Tag
            $dlg.Close()
        }
    })

    $btnCancel.Add_Click({
        $script:dlgResult = $null
        $dlg.Close()
    })

    [void]$dlg.ShowDialog()
    return $script:dlgResult
}

function Search-User {
    $entry = $SearchBox.Text.Trim()
    if ([string]::IsNullOrWhiteSpace($entry)) { return }

    Set-Status "Consultando '$entry'..." "Warning"

    $UserInfoStack.Children.Clear()
    $AccountInfoStack.Children.Clear()
    $GroupsStack.Children.Clear()
    $GroupsCount.Text = "0"
    $BtnUnlock.IsEnabled = $false
    $BtnRefresh.IsEnabled = $false
    Show-EmptyState $false
    Hide-Notification

    if (-not $script:adAvailable) {
        Add-InfoRow $AccountInfoStack "Erro" "Modulo Active Directory nao instalado." "Danger"
        Add-InfoRow $AccountInfoStack "Solucao" "Instale o RSAT: Active Directory Tools." "TextSecond"
        Set-Status "Modulo AD nao disponivel." "Danger"
        return
    }

    $adProperties = @(
        'LockedOut','Enabled','PasswordLastSet','MemberOf','CannotChangePassword','LastLogonDate',
        'PasswordNeverExpires','PasswordExpired','EmailAddress','Title','Department',
        'msDS-UserPasswordExpiryTimeComputed','DisplayName','GivenName','Surname'
    )

    try {
        $u = $null
        $hasSpace = $entry.Contains(' ')

        # Estrategia 1: sAMAccountName direto (se nao houver espacos)
        if (-not $hasSpace) {
            $username = ($entry -split '@')[0]
            try {
                $u = Get-ADUser -Identity $username -Properties $adProperties -ErrorAction Stop
            } catch {
                $u = $null
            }
        }

        # Estrategia 2: busca por nome completo / parcial
        if (-not $u) {
            # Escapar aspas simples para o filtro LDAP do PowerShell
            $safe  = $entry -replace "'", "''"
            $words = $entry -split '\s+' | Where-Object { $_ }

            $filterParts = @()
            $filterParts += "DisplayName -like '*$safe*'"
            $filterParts += "Name -like '*$safe*'"
            $filterParts += "SamAccountName -like '*$safe*'"
            if ($entry -match '@') {
                $filterParts += "EmailAddress -like '*$safe*'"
            }
            if ($words.Count -ge 2) {
                $first = ($words[0])  -replace "'", "''"
                $last  = ($words[-1]) -replace "'", "''"
                $filterParts += "(GivenName -like '*$first*' -and Surname -like '*$last*')"
            }

            $filter = $filterParts -join ' -or '

            $candidates = @()
            try {
                $candidates = @(Get-ADUser -Filter $filter -Properties $adProperties -ErrorAction Stop)
            } catch {
                $candidates = @()
            }

            if ($candidates.Count -eq 0) {
                throw "Usuario '$entry' nao encontrado (nem por login, nem por nome)."
            } elseif ($candidates.Count -eq 1) {
                $u = $candidates[0]
            } else {
                $u = Show-UserSelectionDialog -Users $candidates -Query $entry
                if (-not $u) {
                    Set-Status "Selecao cancelada." "TextDim"
                    Show-EmptyState $true
                    return
                }
            }
        }

        $script:currentUser = $u

        Add-InfoRow $UserInfoStack "Nome completo" $u.Name
        Add-InfoRow $UserInfoStack "Login (sAMAccountName)" $u.SamAccountName
        if ($u.EmailAddress) { Add-InfoRow $UserInfoStack "E-mail" $u.EmailAddress }
        if ($u.Title)        { Add-InfoRow $UserInfoStack "Cargo" $u.Title }
        if ($u.Department)   { Add-InfoRow $UserInfoStack "Departamento" $u.Department }

        if ($u.Enabled) {
            Add-InfoRow $AccountInfoStack "Status da conta" "Conta ativada" "TextPrimary" "ATIVA" "Success" "SuccessBg"
        } else {
            Add-InfoRow $AccountInfoStack "Status da conta" "Conta desativada" "Danger" "DESATIVADA" "Danger" "DangerBg"
        }

        if ($u.LockedOut) {
            Add-InfoRow $AccountInfoStack "Bloqueio" "Conta travada por tentativas" "Danger" "BLOQUEADA" "Danger" "DangerBg"
        } else {
            Add-InfoRow $AccountInfoStack "Bloqueio" "Nao bloqueada" "TextPrimary" "OK" "Success" "SuccessBg"
        }

        $lastLogon = if ($u.LastLogonDate) { $u.LastLogonDate.ToString("dd/MM/yyyy 'as' HH:mm") } else { "Nunca" }
        Add-InfoRow $AccountInfoStack "Ultimo login" $lastLogon

        $pwdLastSet = if ($u.PasswordLastSet) { $u.PasswordLastSet.ToString("dd/MM/yyyy 'as' HH:mm") } else { "Nunca" }
        Add-InfoRow $AccountInfoStack "Ultima troca de senha" $pwdLastSet

        $exp = Get-PasswordExpiryInfo $u
        $expValueColor = if ($exp.IsExpired) { "Danger" } else { "TextPrimary" }
        Add-InfoRow $AccountInfoStack "Senha expira em" $exp.Text $expValueColor $exp.Badge $exp.BadgeKey $exp.BadgeBgKey

        if ($u.CannotChangePassword) {
            Add-InfoRow $AccountInfoStack "Pode trocar senha" "Nao - bloqueado" "Warning"
        }

        if ($exp.IsExpired) {
            Show-Notification "A senha desta conta esta vencida. O usuario nao conseguira efetuar login ate redefinir a senha."
        }

        if ($u.MemberOf) {
            $groups = $u.MemberOf | ForEach-Object { ($_ -split ',')[0].Substring(3) } | Sort-Object
            foreach ($g in $groups) { Add-GroupItem $GroupsStack $g }
            $GroupsCount.Text = [string]$groups.Count
        } else {
            $tb = New-Object System.Windows.Controls.TextBlock
            $tb.Text = "Nenhum grupo encontrado"
            $tb.Foreground = (Get-Brush "TextMute")
            $tb.FontSize = 13
            $tb.FontStyle = "Italic"
            $tb.Margin = "10,8"
            [void]$GroupsStack.Children.Add($tb)
            $GroupsCount.Text = "0"
        }

        $BtnUnlock.IsEnabled  = [bool]$u.LockedOut
        $BtnRefresh.IsEnabled = $true

        # Atualiza caixa de busca para o sAMAccountName real (importante para Refresh)
        $SearchBox.Text = $u.SamAccountName

        Set-Status "Consulta concluida para '$($u.Name)'." "Success"

        # Registrar no historico
        $histStatus = if ($u.LockedOut) { 'Bloqueada' } elseif (-not $u.Enabled) { 'Desativada' } else { 'OK' }
        Add-HistoryEntry -Username $u.SamAccountName -Name $u.Name -Status $histStatus

    } catch {
        Show-EmptyState $false
        Add-InfoRow $AccountInfoStack "Erro" "Usuario '$entry' nao encontrado" "Danger"
        Add-InfoRow $AccountInfoStack "Detalhes" $_.Exception.Message "TextDim"
        Set-Status "Falha na consulta: usuario nao encontrado." "Danger"
    }
}

# ===================== EVENTOS =====================
$AdminLabel.Text = "$env:USERNAME @ $env:USERDOMAIN"

$SearchBox.Add_TextChanged({
    if ([string]::IsNullOrEmpty($SearchBox.Text)) {
        $SearchHint.Visibility = 'Visible'
    } else {
        $SearchHint.Visibility = 'Collapsed'
    }
})

$SearchBox.Add_KeyDown({
    param($s, $e)
    if ($e.Key -eq 'Return') { Search-User; $e.Handled = $true }
})

$SearchButton.Add_Click({ Search-User })

$BtnUnlock.Add_Click({
    if (-not $script:currentUser) { return }
    try {
        Unlock-ADAccount -Identity $script:currentUser.SamAccountName -ErrorAction Stop
        Set-Status "Conta '$($script:currentUser.SamAccountName)' desbloqueada com sucesso." "Success"
        Search-User
    } catch {
        Set-Status "Falha ao desbloquear: $($_.Exception.Message)" "Danger"
    }
})

$BtnRefresh.Add_Click({ Search-User })

$BtnScreenshot.Add_Click({
    $width = [int]$window.ActualWidth
    $height = [int]$window.ActualHeight
    $rtb = New-Object System.Windows.Media.Imaging.RenderTargetBitmap($width, $height, 96, 96, [System.Windows.Media.PixelFormats]::Pbgra32)
    
    $rtb.Render($window)
    [System.Windows.Clipboard]::SetImage($rtb)
    
    Set-Status "Screenshot copiado para a área de transferência!" "Success"
})

$BtnClearHistory.Add_Click({
    $res = [System.Windows.MessageBox]::Show(
        'Deseja realmente limpar todo o historico de consultas?',
        'Limpar historico',
        [System.Windows.MessageBoxButton]::YesNo,
        [System.Windows.MessageBoxImage]::Question)
    if ($res -eq [System.Windows.MessageBoxResult]::Yes) {
        Clear-History
        Set-Status 'Historico de consultas limpo.' 'TextDim'
    }
})

$window.Add_Loaded({
    Load-History
    Render-History
    $SearchBox.Focus() | Out-Null
})

[void]$window.ShowDialog()
